		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 85, "<script>\n\t\t// ============================================\n\t\t// COPY LINK\n\t\t// ============================================\n\t\twindow.copyInvitationLink = function(path, title) {\n\t\t\tvar fullUrl = window.location.origin + path;\n\t\t\tif (navigator.clipboard) {\n\t\t\t\tnavigator.clipboard.writeText(fullUrl).then(function() {\n\t\t\t\t\talert('✅ Link tersalin!\\n\\n' + title + '\\n' + fullUrl);\n\t\t\t\t}).catch(function() {\n\t\t\t\t\talert('Link: ' + fullUrl);\n\t\t\t\t});\n\t\t\t} else {\n\t\t\t\talert('Link: ' + fullUrl);\n\t\t\t}\n\t\t};\n\n\t\t// ============================================\n\t\t// OPEN ACTION MODAL\n\t\t// ============================================\n\t\twindow.openActionModal = function(id, title, slug, status, rsvpCount) {\n\t\t\t// Isi subtitle\n\t\t\tdocument.getElementById('actionModalSubtitle').textContent = title;\n\n\t\t\t// Isi link\n\t\t\tdocument.getElementById('actionRsvp').href = '/admin/projects/' + id + '/rsvp';\n\t\t\tdocument.getElementById('actionShare').href = '/share/invitation/' + id;\n\t\t\tdocument.getElementById('actionDetail').href = '/admin/projects/' + id;\n\t\t\tdocument.getElementById('actionEdit').href = '/invitation/create/edit/' + id;\n\t\t\tdocument.getElementById('actionView').href = '/invitation/' + slug;\n\t\t\tdocument.getElementById('actionDeleteForm').action = '/admin/projects/' + id + '/delete';\n\n\t\t\t// Badge RSVP\n\t\t\tvar rsvpBadge = document.getElementById('rsvpBadge');\n\t\t\tvar count = parseInt(rsvpCount, 10);\n\t\t\tif (count > 0) {\n\t\t\t\trsvpBadge.textContent = count;\n\t\t\t\trsvpBadge.style.display = 'inline-block';\n\t\t\t} else {\n\t\t\t\trsvpBadge.style.display = 'none';\n\t\t\t}\n\n\t\t\t// Sembunyikan tombol \"Lihat Undangan\" kalau belum published\n\t\t\tvar actionView = document.getElementById('actionView');\n\t\t\tif (status !== 'published') {\n\t\t\t\tactionView.style.opacity = '0.4';\n\t\t\t\tactionView.style.pointerEvents = 'none';\n\t\t\t\tactionView.title = 'Undangan belum dipublikasikan';\n\t\t\t} else {\n\t\t\t\tactionView.style.opacity = '1';\n\t\t\t\tactionView.style.pointerEvents = 'auto';\n\t\t\t\tactionView.title = '';\n\t\t\t}\n\n\t\t\t// Show modal\n\t\t\tvar modalEl = document.getElementById('actionModal');\n\t\t\tvar modal = bootstrap.Modal.getOrCreateInstance(modalEl);\n\t\t\tmodal.show();\n\t\t};\n\n\t\t// ============================================\n\t\t// GANTI TEMA MODAL\n\t\t// ============================================\n\t\tvar _adminProjectID = 0;\n\t\tvar _adminCurrentTemplateID = 0;\n\t\tvar _adminSelectedTemplateID = 0;\n\n\t\twindow.openTemplateChangeModal = function() {\n\t\t\tvar projectTitle = document.getElementById('actionModalSubtitle').textContent || '-';\n\n\t\t\t// Extract project ID dari actionDeleteForm.action\n\t\t\tvar deleteForm = document.getElementById('actionDeleteForm');\n\t\t\tvar actionUrl = deleteForm ? deleteForm.action : '';\n\t\t\tvar match = actionUrl.match(/\\/admin\\/projects\\/(\\d+)/);\n\t\t\t_adminProjectID = match ? parseInt(match[1]) : 0;\n\n\t\t\t// Cari current template ID dari row (kalau ada data attribute)\n\t\t\t_adminCurrentTemplateID = 0;\n\t\t\tvar rows = document.querySelectorAll('tr[data-project-id]');\n\t\t\trows.forEach(function(r) {\n\t\t\t\tif (parseInt(r.dataset.projectId) === _adminProjectID) {\n\t\t\t\t\t_adminCurrentTemplateID = parseInt(r.dataset.templateId || 0);\n\t\t\t\t}\n\t\t\t});\n\t\t\t_adminSelectedTemplateID = _adminCurrentTemplateID;\n\n\t\t\tdocument.getElementById('templateChangeSubtitle').textContent = projectTitle;\n\n\t\t\t// Reset\n\t\t\tdocument.querySelectorAll('.template-change-card').forEach(function(c) {\n\t\t\t\tc.classList.remove('selected');\n\t\t\t\tc.style.borderColor = '#2a2a2a';\n\t\t\t\tc.style.background = '#0f0f0f';\n\t\t\t\tvar chk = c.querySelector('.template-change-check');\n\t\t\t\tif (chk) chk.style.display = 'none';\n\t\t\t});\n\n\t\t\t// Auto-select current\n\t\t\tif (_adminCurrentTemplateID > 0) {\n\t\t\t\tdocument.querySelectorAll('.template-change-card').forEach(function(c) {\n\t\t\t\t\tif (parseInt(c.dataset.templateId) === _adminCurrentTemplateID) {\n\t\t\t\t\t\tc.classList.add('selected');\n\t\t\t\t\t\tc.style.borderColor = '#8b5cf6';\n\t\t\t\t\t\tc.style.background = 'rgba(139,92,246,0.08)';\n\t\t\t\t\t\tvar chk = c.querySelector('.template-change-check');\n\t\t\t\t\t\tif (chk) chk.style.display = 'flex';\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t}\n\n\t\t\tupdateAdminTemplateSaveBtn();\n\n\t\t\t// Tutup actionModal, buka templateChangeModal\n\t\t\tvar actionModalEl = document.getElementById('actionModal');\n\t\t\tvar actionModalInstance = bootstrap.Modal.getInstance(actionModalEl);\n\t\t\tif (actionModalInstance) actionModalInstance.hide();\n\n\t\t\tsetTimeout(function() {\n\t\t\t\tvar tplModalEl = document.getElementById('templateChangeModal');\n\t\t\t\tvar tplModal = bootstrap.Modal.getOrCreateInstance(tplModalEl);\n\t\t\t\ttplModal.show();\n\t\t\t}, 300);\n\t\t};\n\n\t\twindow.selectTemplateChangeCard = function(card) {\n\t\t\tdocument.querySelectorAll('.template-change-card').forEach(function(c) {\n\t\t\t\tc.classList.remove('selected');\n\t\t\t\tc.style.borderColor = '#2a2a2a';\n\t\t\t\tc.style.background = '#0f0f0f';\n\t\t\t\tvar chk = c.querySelector('.template-change-check');\n\t\t\t\tif (chk) chk.style.display = 'none';\n\t\t\t});\n\t\t\tcard.classList.add('selected');\n\t\t\tcard.style.borderColor = '#8b5cf6';\n\t\t\tcard.style.background = 'rgba(139,92,246,0.08)';\n\t\t\tvar chk = card.querySelector('.template-change-check');\n\t\t\tif (chk) chk.style.display = 'flex';\n\n\t\t\t_adminSelectedTemplateID = parseInt(card.dataset.templateId);\n\t\t\tupdateAdminTemplateSaveBtn();\n\t\t};\n\n\t\tfunction updateAdminTemplateSaveBtn() {\n\t\t\tvar btn = document.getElementById('templateChangeSaveBtn');\n\t\t\tif (!btn) return;\n\t\t\tbtn.disabled = (_adminSelectedTemplateID === 0);\n\t\t}\n\n\t\twindow.submitAdminChangeTemplate = function() {\n\t\t\tif (!_adminProjectID || !_adminSelectedTemplateID) return;\n\n\t\t\tvar btn = document.getElementById('templateChangeSaveBtn');\n\t\t\tvar originalHtml = btn.innerHTML;\n\t\t\tbtn.disabled = true;\n\t\t\tbtn.innerHTML = '<i class=\"bi bi-hourglass-split me-1\"></i>Menyimpan...';\n\n\t\t\tfetch('/admin/projects/' + _adminProjectID + '/change-template', {\n\t\t\t\tmethod: 'POST',\n\t\t\t\theaders: {\n\t\t\t\t\t'Content-Type': 'application/json',\n\t\t\t\t\t'X-Requested-With': 'XMLHttpRequest',\n\t\t\t\t\t'Accept': 'application/json'\n\t\t\t\t},\n\t\t\t\tbody: JSON.stringify({ template_id: _adminSelectedTemplateID })\n\t\t\t})\n\t\t\t.then(function(r) { return r.json(); })\n\t\t\t.then(function(data) {\n\t\t\t\tif (data.success) {\n\t\t\t\t\tvar tplModalEl = document.getElementById('templateChangeModal');\n\t\t\t\t\tvar tplModal = bootstrap.Modal.getInstance(tplModalEl);\n\t\t\t\t\tif (tplModal) tplModal.hide();\n\t\t\t\t\tsetTimeout(function() { window.location.reload(); }, 400);\n\t\t\t\t} else {\n\t\t\t\t\talert('Gagal: ' + (data.message || 'Terjadi kesalahan'));\n\t\t\t\t\tbtn.disabled = false;\n\t\t\t\t\tbtn.innerHTML = originalHtml;\n\t\t\t\t}\n\t\t\t})\n\t\t\t.catch(function(err) {\n\t\t\t\talert('Error: ' + err.message);\n\t\t\t\tbtn.disabled = false;\n\t\t\t\tbtn.innerHTML = originalHtml;\n\t\t\t});\n\t\t};\n\t</script>")
